function Pad:ToggleMenu()
    if self.menu and self.menu:IsShown() then
        self:CloseMenu()
        return
    end
    if not self.menu then self:CreateMenu() end
    self:UpdateMenuAvailability()
    self:LayoutMenu()
    self:ShowMenuPage(1)
    self.menu:Show()
    self.menu:Raise()
    self:FocusWindow(self.menu)
    self:RequestFocus(self.menuPages[1].frame)
end --[[APR_DIAG]]
